def merge(intervals):
    """Merge overlapping or touching [start, end] intervals.

    Returns a new list of disjoint intervals sorted by start, without
    modifying the input.
    """
    sorted_intervals = sorted([list(iv) for iv in intervals], key=lambda iv: (iv[0], iv[1]))
    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
